-- preflight for 11 (SELECT only): 08 applied? sets with stale items / existing drafts
-- generated by scripts/prod-open/sat-expand-sql.ts (SAT_11=1 or SAT_24=1). Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.

select s.name, s.version_no, count(*) filter (where p.published_version_id is distinct from i.problem_version_id and i.problem_id = any (array['4cc47e7c-e766-47d8-aa9b-ae16aeb96d71','9977438d-6d27-48ed-aebb-c4ad8e08c6c0','f59b7f57-b596-4235-9902-d8036d9040ff','7ddfae40-f506-48b2-a2c2-fd8dab606f30']::uuid[])) as stale_manual_items,
  (select count(*) from mock_exam_sets d where d.set_group_id = s.set_group_id and d.status = 'draft') as existing_drafts
from mock_exam_sets s join mock_exam_set_items i on i.exam_set_id = s.id join problems p on p.id = i.problem_id
where s.status = 'published' and s.archived_at is null and s.name = any (array['SAT Practice Test 1','SAT Practice Test 2','SAT Practice Test 3','SAT Practice Test 21']) group by s.name, s.version_no, s.set_group_id order by length(s.name), s.name;
select count(*) as patched_08_versions from problems p join problem_versions pv on pv.id = p.published_version_id where p.id = any (array['4cc47e7c-e766-47d8-aa9b-ae16aeb96d71','9977438d-6d27-48ed-aebb-c4ad8e08c6c0','f59b7f57-b596-4235-9902-d8036d9040ff','7ddfae40-f506-48b2-a2c2-fd8dab606f30']::uuid[]) and pv.quality->'auditFix'->>'patch' like 'E1019-X%';
